// CSD_RATIONALE_BEGIN
// Best result (attempt 43): 52% accuracy / 99% syntax using immediate
// IsCompletePrefix → close.  The remaining 48% gap has two root causes:
//
// 1. PREMATURE CLOSURE (primary, ~100 cases in mode_A):  Spider SQL always
//    requires a FROM clause, but the SQL grammar used by the parser accepts
//    "SELECT col" as a complete prefix.  When the model emits "SELECT city",
//    IsCompletePrefix fires and attempt 43 closes the span immediately,
//    yielding syntactically valid but semantically wrong SQL.
//
// 2. SEMANTIC MISMATCH WITH FROM PRESENT (~46 cases):  The model uses wrong
//    table/column names or missing WHERE/GROUP BY/HAVING, a problem addressed
//    partly by ValidTokenGroups boosting.
//
// This attempt keeps attempt 43's verified structure and adds one targeted
// semantic fix: a FROM-token guard before closing.
//
//   - When IsCompletePrefix fires AND "FROM" (or "from" / " FROM" / " from")
//     appears as a token in currentConstrainedOut → close immediately (same
//     behaviour as attempt 43, preserves the 99% syntax rate).
//   - When IsCompletePrefix fires but no FROM token found → call
//     SafeBoostedConstrainedStep boosting ["FROM"," FROM","from"," from"] by
//     5.0, so the model is guided to extend the SELECT with a FROM clause
//     rather than stopping.
//   - Non-complete → GroupBoostedConstrainedStep(6.0) as in attempt 43.
//   - Phase 4 CloseSpanWithinBudget(≤80) fallback unchanged.
//   - Guidance emphasises mandatory FROM clause.
//
// Only helpers in the approved set are used; no non-existent calls.
// CSD_RATIONALE_END

// CSD_PROOF_SKETCH_BEGIN
// Invariant 1 (parser_validity):
//   insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
//
// Phase 1 (unconstrained preamble): insideConstrainedOut can only flip to true
//   when RenderedEndsWith(generated, "<<") fires, at which point we set
//   currentConstrainedOut := [], which satisfies IsValidPrefix([]) by the method
//   precondition.  An EOS break leaves insideConstrainedOut false; vacuously true.
//
// Phase 2 (OpenConstrainedSpan): Only runs when !insideConstrainedOut.  The
//   helper sets currentConstrainedOut := []; valid by precondition.
//
// Phase 3 main loop:
//   "Complete+hasFrom" branch: CloseConstrainedSpan sets insideConstrainedOut :=
//     false, making the implication vacuously true and clearing currentConstrainedOut.
//   "Complete+noFrom" branch: SafeBoostedConstrainedStep hard-masks to parser-valid
//     tokens + EOS.  On non-EOS, AppendConstrainedToken extends currentConstrainedOut
//     by one valid token, preserving IsValidPrefix by the parser extension contract.
//     On EOS+close: CloseConstrainedSpan sets insideConstrainedOut := false.
//     On EOS+break (budget): invariant holds by induction hypothesis.
//   "Not complete" branch: GroupBoostedConstrainedStep hard-masks to parser-valid
//     tokens + EOS.  AppendConstrainedToken preserves IsValidPrefix.
//     On EOS+close: CloseConstrainedSpan sets insideConstrainedOut := false.
//     On EOS+break: invariant by induction.
//
// Phase 4 (CloseSpanWithinBudget): postcondition guarantees
//   insideOut ==> parser.IsValidPrefix(currentOut).
//
// Invariant 2 (progress):
//   |generated| <= |generatedPrefix| + steps
//
// Phase 1: Each iteration steps += 1; |generated| grows by 0 (EOS) or 1
//   (token).  Ratio <= 1:1.
// Phase 2: steps += 1; |generated| grows by exactly 1 ("<<").  1:1.
// Phase 3:
//   "Complete+hasFrom": steps += 1; CloseConstrainedSpan appends <= 1 (">>").
//   "Complete+noFrom", non-EOS: steps += 1; AppendConstrainedToken appends 1.
//   "Complete+noFrom", EOS+close: steps += 2; close appends <= 1; ratio < 1.
//   "Complete+noFrom", EOS+break: steps += 1; 0 tokens appended; strict improvement.
//   "Not complete", non-EOS: steps += 1; AppendConstrainedToken appends 1. 1:1.
//   "Not complete", EOS+close: steps += 2; close appends <= 1; ratio < 1.
//   "Not complete", EOS+break: steps += 1; 0 tokens; strict improvement.
// Phase 4: CloseSpanWithinBudget postcondition |generatedOut| <= |generated| +
//   closeBudget; steps += closeBudget.  Invariant preserved.
// CSD_PROOF_SKETCH_END

generated := generatedPrefix;
insideConstrainedOut := insideConstrained;
currentConstrainedOut := currentConstrained;
cost := 0;

helpers.AppendTaskGuidance(lm, "Output SQL: <<query>> where query is a complete SQL SELECT statement that always includes a FROM clause. Use ONLY exact table and column names from the schema. Structure: SELECT ... FROM <table> [JOIN ...] [WHERE ...] [GROUP BY ...] [HAVING ...] [ORDER BY ...] [LIMIT ...]. No table aliases unless explicitly defined in the schema. No explanations outside the delimiters.");

var steps: nat := 0;

// Phase 1: Short unconstrained preamble (at most 5 steps) for "SQL: " prefix
while steps < maxSteps && steps < 5 && !insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  var next := helpers.UnconstrainedStep(lm, prompt, generated);
  steps := steps + 1;
  if next == eosToken {
    break;
  } else {
    generated := generated + [next];
    if RenderedEndsWith(generated, "<<") {
      insideConstrainedOut := true;
      currentConstrainedOut := [];
    }
  }
}

// Phase 2: Force open "<<" if not already inside a constrained span
if !insideConstrainedOut && steps < maxSteps {
  var og, oi, oc := helpers.OpenConstrainedSpan(lm, generated);
  generated := og;
  insideConstrainedOut := oi;
  currentConstrainedOut := oc;
  steps := steps + 1;
}

// Phase 3: Generate SQL under hard constrained control with FROM-clause guard
while steps < maxSteps && insideConstrainedOut
  invariant 0 <= steps <= maxSteps
  invariant lm.ValidTokensIdsLogits()
  invariant !insideConstrainedOut ==> currentConstrainedOut == []
  invariant insideConstrainedOut ==> parser.IsValidPrefix(currentConstrainedOut)
  invariant insideConstrainedOut ==> |currentConstrainedOut| <= |generated|
  invariant |generated| <= |generatedPrefix| + steps
  decreases maxSteps - steps
{
  // Check for FROM keyword in multiple token forms
  var fromU  := CSDHelpers.CountTokenOccurrences(currentConstrainedOut, "FROM");
  var fromL  := CSDHelpers.CountTokenOccurrences(currentConstrainedOut, "from");
  var fromSU := CSDHelpers.CountTokenOccurrences(currentConstrainedOut, " FROM");
  var fromSL := CSDHelpers.CountTokenOccurrences(currentConstrainedOut, " from");
  var hasFrom := fromU + fromL + fromSU + fromSL > 0;

  var constrainedPrompt := prompt + generated[..|generated| - |currentConstrainedOut|];

  if parser.IsCompletePrefix(currentConstrainedOut) && hasFrom {
    // Complete SQL with FROM clause present: close the span
    var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
    generated := cg;
    insideConstrainedOut := ci;
    currentConstrainedOut := cc;
    steps := steps + 1;
    break;
  } else if parser.IsCompletePrefix(currentConstrainedOut) {
    // Complete SQL but no FROM clause yet: boost FROM tokens to push continuation
    var next := helpers.SafeBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut,
      ["FROM", " FROM", "from", " from"], 5.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      // Model stopped even with FROM boost; close the best parse we have
      if steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  } else {
    // SQL not yet complete: standard group-boosted constrained step
    var next := helpers.GroupBoostedConstrainedStep(
      lm, parser, constrainedPrompt, currentConstrainedOut, validTokenGroups, 6.0, eosToken
    );
    steps := steps + 1;
    if next == eosToken {
      if parser.IsCompletePrefix(currentConstrainedOut) && steps < maxSteps {
        var cg, ci, cc := helpers.CloseConstrainedSpan(lm, parser, generated, currentConstrainedOut);
        generated := cg;
        insideConstrainedOut := ci;
        currentConstrainedOut := cc;
        steps := steps + 1;
      }
      break;
    } else {
      var ag, ai, ac := helpers.AppendConstrainedToken(
        lm, parser, generated, currentConstrainedOut, next
      );
      generated := ag;
      insideConstrainedOut := ai;
      currentConstrainedOut := ac;
    }
  }
}

// Phase 4: Fallback closure if span is still open
if insideConstrainedOut && steps < maxSteps {
  var remaining := maxSteps - steps;
  var closeBudget: nat;
  if remaining <= 80 {
    closeBudget := remaining;
  } else {
    closeBudget := 80;
  }
  var cg, ci, cc := helpers.CloseSpanWithinBudget(
    lm, parser, prompt, generated, currentConstrainedOut, eosToken, closeBudget
  );
  generated := cg;
  insideConstrainedOut := ci;
  currentConstrainedOut := cc;
  steps := steps + closeBudget;
}

cost := steps;

